local({
  grade <- if_else(GRADE %in% c("T", "K", "P", as.character(1:12)), GRADE, GRADEEQ)
  case_when(
    grade == "T" ~ "Transitional kindergarten",
    grade == "K" ~ "Kindergarten",
    grade == "P" ~ "Pre-first grade",
    grade %in% as.character(1:12) ~ paste("Grade", grade),
    .default = NA_character_
  )
})

local({
  wd <- case_when(TVHRWKDY %in% c(2, 3) ~ 0, TVHRWKDY == 1 ~ TVWKDYNU, .default = NA_real_)
  we <- case_when(TVHRWKDY == 3 | TVHRWKND == 2 ~ 0, TVHRWKND == 1 ~ TVWKNDNU, .default = NA_real_)
  (5 * wd + 2 * we) / 7
})
